-- PostgreSQL 18, UUID native columns. Application must pass the same UUID across all logs.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS agent_runs(run_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),status VARCHAR(20) NOT NULL CHECK(status IN ('RUNNING','SUCCESS','FAILED')),started_at TIMESTAMPTZ NOT NULL DEFAULT now(),finished_at TIMESTAMPTZ,duration_ms INTEGER CHECK(duration_ms>=0),error_source VARCHAR(20),error_code VARCHAR(100),failed_step_name VARCHAR(100),route TEXT,companion_type VARCHAR(50));
CREATE TABLE IF NOT EXISTS agent_step_logs(step_log_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),run_id UUID NOT NULL REFERENCES agent_runs(run_id),step_order INTEGER NOT NULL,agent_name VARCHAR(100) NOT NULL,step_name VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('RUNNING','SUCCESS','FAILED')),started_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,duration_ms INTEGER CHECK(duration_ms>=0),error_source VARCHAR(20),error_code VARCHAR(100));
CREATE TABLE IF NOT EXISTS api_call_logs(api_call_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),run_id UUID NOT NULL REFERENCES agent_runs(run_id),provider VARCHAR(100) NOT NULL,api_type VARCHAR(30) NOT NULL,http_status INTEGER,latency_ms INTEGER NOT NULL CHECK(latency_ms>=0),success BOOLEAN NOT NULL,called_at TIMESTAMPTZ NOT NULL,error_source VARCHAR(20),error_code VARCHAR(100));
CREATE TABLE IF NOT EXISTS handoff_logs(handoff_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),run_id UUID NOT NULL REFERENCES agent_runs(run_id),from_agent VARCHAR(100) NOT NULL,to_agent VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('RUNNING','SUCCESS','FAILED')),started_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,duration_ms INTEGER CHECK(duration_ms>=0),error_source VARCHAR(20),error_code VARCHAR(100));
CREATE TABLE IF NOT EXISTS incident_logs(incident_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),run_id UUID NOT NULL REFERENCES agent_runs(run_id),api_call_id UUID REFERENCES api_call_logs(api_call_id),status VARCHAR(20) NOT NULL CHECK(status IN ('OPEN','RECOVERING','RESOLVED')),severity VARCHAR(20) NOT NULL,error_source VARCHAR(20) NOT NULL,error_code VARCHAR(100) NOT NULL,error_message TEXT,failed_step_name VARCHAR(100),occurred_at TIMESTAMPTZ NOT NULL,resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS recovery_logs(recovery_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),incident_id UUID NOT NULL REFERENCES incident_logs(incident_id),run_id UUID NOT NULL REFERENCES agent_runs(run_id),attempt_number INTEGER NOT NULL,recovery_action VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('RUNNING','RECOVERED','FAILED')),started_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,duration_ms INTEGER CHECK(duration_ms>=0),UNIQUE(incident_id,attempt_number));
CREATE INDEX IF NOT EXISTS idx_agent_step_run ON agent_step_logs(run_id);
CREATE INDEX IF NOT EXISTS idx_api_call_run ON api_call_logs(run_id);
CREATE INDEX IF NOT EXISTS idx_handoff_run ON handoff_logs(run_id);
CREATE INDEX IF NOT EXISTS idx_incident_run ON incident_logs(run_id);
CREATE INDEX IF NOT EXISTS idx_recovery_incident ON recovery_logs(incident_id);
